+                "x mirrors: {ps:?} vs {pd:?}"
+            );
+            assert!(
+                (ps.y - (20.0 - pd.y)).abs() < TIGHT,
+                "y mirrors: {ps:?} vs {pd:?}"
+            );
+            assert!((ps.z - pd.z).abs() < TIGHT, "z holds: {ps:?} vs {pd:?}");
+        }
+    }
